using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Cysharp.Threading.Tasks;
using Game.Access;
using Game.Revive;
using MiniFramework.Contracts;
using MiniFramework.Storage;
using MiniFramework.Providers.StorageEditor;
using NUnit.Framework;
using UnityEngine.TestTools;
using ReviveTests;
public sealed class ReviveDiskTests
{
    readonly List<Env> envs=new List<Env>();readonly List<string> roots=new List<string>();
    string Root(){var p=Path.GetFullPath("Library/S406Test-"+Guid.NewGuid().ToString("N"));roots.Add(p);return p;}
    Env New(string root,MiniFramework.Ads.AdReceiptJournal facts=null,string owner=Env.OwnerId){var e=new Env(facts:facts,provider:new EditorStorageProvider(root),ownerId:owner);envs.Add(e);return e;}
    [UnityTearDown] public IEnumerator Teardown(){yield return UniTask.ToCoroutine(async()=>{foreach(var e in envs)await e.Finish();foreach(var r in roots)if(Directory.Exists(r))Directory.Delete(r,true);envs.Clear();roots.Clear();});}
    [UnityTest] public IEnumerator DiskGrantAndProgressRestoreTogether()=>UniTask.ToCoroutine(async()=>{var root=Root();var e=New(root);await e.Start();await e.FailedRun();var r=await e.Capture().WaitAsync(Env.Wait);Assert.IsTrue(r.IsSuccess&&r.Value.IsDurable);Env.Check(await e.Context.CloseAsync(Env.Wait));var reopened=New(root,e.Facts);await reopened.Start();Assert.AreEqual(5,reopened.Store.Snapshot.Coins);Assert.AreEqual(ReviveRunPhase.Playing,reopened.Store.Snapshot.Phase);Assert.IsTrue(reopened.Store.Snapshot.ReviveUsed);Assert.AreEqual(ReviveClaimState.Granted,reopened.Store.Snapshot.Claims.Single().State);Assert.AreEqual(0,reopened.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator GenerationReservationSurvivesFreshOwnerSource()=>UniTask.ToCoroutine(async()=>{var root=Root();var a=New(root);await a.Start();var first=a.Owner.CurrentOwner.Value.SessionGeneration;Env.Check(await a.Context.CloseAsync(Env.Wait));var b=New(root);await b.Start();Assert.Greater(b.Owner.CurrentOwner.Value.SessionGeneration,first);Assert.AreEqual(b.Owner.CurrentOwner.Value.SessionGeneration,b.Store.Snapshot.LastGeneration);});
    [UnityTest] public IEnumerator RejectedGrantRetainsPendingAndExplicitRetryDoesNotShow()=>UniTask.ToCoroutine(async()=>{var root=Root();var provider=new EditorStorageProvider(root);var e=new Env(provider:provider);envs.Add(e);e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var task=e.Capture().WaitAsync(Env.Wait);provider.NextFault=EditorStorageFault.BeforeReplace;e.Attempt.CompleteShow();Assert.IsFalse((await task).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsNotNull(e.Store.Snapshot.Pending);var grant=await e.Service.RecoverPendingAsync(Env.Wait);Assert.IsTrue(grant.IsSuccess&&grant.Value.IsDurable);Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(5,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator UnknownAfterReplaceReopensGrantedWithoutReplay()=>UniTask.ToCoroutine(async()=>{var root=Root();var provider=new EditorStorageProvider(root);var e=new Env(provider:provider);envs.Add(e);e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var task=e.Capture().WaitAsync(Env.Wait);provider.NextFault=EditorStorageFault.AfterReplace;e.Attempt.CompleteShow();Assert.IsFalse((await task).IsSuccess);Assert.IsTrue(e.Store.RecoveryRequired);Env.Check(await e.Context.CloseAsync(Env.Wait));var next=New(root,e.Facts);await next.Start();Assert.AreEqual(5,next.Store.Snapshot.Coins);Assert.IsNull(next.Store.Snapshot.Pending);Assert.IsFalse((await next.Service.RecoverPendingAsync(Env.Wait)).IsSuccess);Assert.AreEqual(0,next.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator CorruptDiskIsNotOverwrittenByStartup()=>UniTask.ToCoroutine(async()=>{var root=Root();var p=new EditorStorageProvider(root);var path=p.PathFor(Env.Address);Directory.CreateDirectory(Path.GetDirectoryName(path));var bad=new byte[]{1,2,3};File.WriteAllBytes(path,bad);var e=New(root);Assert.IsFalse((await e.Context.StartAsync(Env.Wait)).IsSuccess);CollectionAssert.AreEqual(bad,File.ReadAllBytes(path));Assert.IsNull(e.Owner.CurrentOwner);});
    [UnityTest] public IEnumerator DifferentInstallationOwnerCannotClaimExistingSave()=>UniTask.ToCoroutine(async()=>{var root=Root();var e=New(root);await e.Start();Env.Check(await e.Context.CloseAsync(Env.Wait));var path=new EditorStorageProvider(root).PathFor(Env.Address);var before=File.ReadAllBytes(path);var other=New(root,owner:"other-installation");Assert.IsFalse((await other.Context.StartAsync(Env.Wait)).IsSuccess);CollectionAssert.AreEqual(before,File.ReadAllBytes(path));});
    [UnityTest] public IEnumerator UnknownOptionalModuleSurvivesCounterAndGrant()=>UniTask.ToCoroutine(async()=>{var root=Root();var e=New(root);await e.Start();Env.Check(await e.Context.CloseAsync(Env.Wait));var p=new EditorStorageProvider(root);var path=p.PathFor(Env.Address);var old=StorageFormat.Decode(File.ReadAllBytes(path),new StorageLimits()).Value;var records=old.Records.Concat(new[]{new StorageRecord("optional.future",9,"future.codec",false,new byte[]{9,8,7})});File.WriteAllBytes(path,StorageFormat.Encode(new StorageContainer(Env.Address,old.Sequence,records),new StorageLimits()).Value);var next=New(root);await next.Start();await next.FailedRun();Assert.IsTrue((await next.Capture().WaitAsync(Env.Wait)).IsSuccess);Env.Check(await next.Context.CloseAsync(Env.Wait));var final=StorageFormat.Decode(File.ReadAllBytes(path),new StorageLimits()).Value;CollectionAssert.AreEqual(new byte[]{9,8,7},final.Records.Single(r=>r.ModuleId=="optional.future").CopyPayload());});
    [UnityTest] public IEnumerator GrantedSequenceAheadOfContainerIsRejected()=>UniTask.ToCoroutine(async()=>{var root=Root();var owner=new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,Env.OwnerId,1,Env.Ns);var claim=new ReviveClaim("c","a","r",owner,1,5,PlatformExecutionMode.Mock,ReviveClaimState.Granted,99);var snapshot=new ReviveSnapshot(owner.Mode,owner.OwnerId,owner.StorageNamespace,1,5,"r",1,ReviveRunPhase.Playing,true,claims:new[]{claim});var bytes=StorageFormat.Encode(new StorageContainer(Env.Address,1,new[]{new StorageRecord(ReviveCodec.ModuleId,1,ReviveCodec.CodecId,true,ReviveCodec.Encode(snapshot).Value)}),new StorageLimits()).Value;var path=new EditorStorageProvider(root).PathFor(Env.Address);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,bytes);var e=New(root);Assert.IsFalse((await e.Context.StartAsync(Env.Wait)).IsSuccess);CollectionAssert.AreEqual(bytes,File.ReadAllBytes(path));});
    [UnityTest] public IEnumerator RepeatedReopenNeverReaddsReward()=>UniTask.ToCoroutine(async()=>{var root=Root();var e=New(root);await e.Start();await e.FailedRun();await e.Capture().WaitAsync(Env.Wait);Env.Check(await e.Context.CloseAsync(Env.Wait));for(var i=0;i<3;i++){var n=New(root,e.Facts);await n.Start();Assert.AreEqual(5,n.Store.Snapshot.Coins);Assert.AreEqual(1,n.Store.Snapshot.Claims.Count);Env.Check(await n.Context.CloseAsync(Env.Wait));}});
    [UnityTest] public IEnumerator WriteIndependentDiskReadProof()=>UniTask.ToCoroutine(async()=>{var root=Root();var e=New(root);await e.Start();await e.FailedRun();Assert.IsTrue((await e.Capture().WaitAsync(Env.Wait)).Value.IsDurable);Env.Check(await e.Context.CloseAsync(Env.Wait));var path=new EditorStorageProvider(root).PathFor(Env.Address);var destination=Path.GetFullPath("Library/S406DiskProof-"+Guid.NewGuid().ToString("N"));Directory.Move(root,destination);var relative=path.Substring(root.Length+1);File.WriteAllText("Library/S406DiskProof.json","{\"root\":\""+destination+"\",\"path\":\""+Path.Combine(destination,relative)+"\",\"sha256\":\""+StorageFormat.Digest(File.ReadAllBytes(Path.Combine(destination,relative)))+"\"}");});
}
